#include <stdio.h>
#include <string.h>
int is_good(int x, char dig) {
    char s[20]; sprintf(s, "%d", x);
    int len = strlen(s);
    for (int i = 0; i < len; i++) if (s[i] == dig) return 0;
    for (int i = 0; i < len - 1; i++) {
        int d = s[i] - '0', sum_r = 0;
        for (int j = i + 1; j < len; j++) sum_r += s[j] - '0';
        if (d <= sum_r) return 0;
    }
    return 1;
}
int main() {
    int l, r; char dig[10];
    if (scanf("%d %d %s", &l, &r, dig) != 3) return 0;
    int first = 1;
    for (int x = l; x <= r; x++) {
        if (is_good(x, dig[0])) {
            if (!first) putchar(' ');
            printf("%d", x); first = 0;
        }
    }
    putchar('\n');
    return 0;
}

