import sys
def main():
    toks = sys.stdin.read().split()
    if len(toks) >= 3:
        L, R, dig = int(toks[0]), int(toks[1]), toks[2]
        res = []
        for x in range(L, R + 1):
            s = str(x)
            if dig in s: continue
            is_good = True
            for i in range(len(s) - 1):
                d = int(s[i])
                sum_right = sum(int(c) for c in s[i+1:])
                if d <= sum_right: is_good = False; break
            if is_good: res.append(str(x))
        print(" ".join(res))
