const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length >= 3) {
        const L = parseInt(toks[0], 10), R = parseInt(toks[1], 10), dig = toks[2];
        const res = [];
        for (let x = L; x <= R; x++) {
            const s = x.toString();
            if (s.includes(dig)) continue;
            let isGood = true;
            for (let i = 0; i < s.length - 1; i++) {
                const d = parseInt(s[i], 10);
                let sumR = 0;
                for (let j = i + 1; j < s.length; j++) sumR += parseInt(s[j], 10);
                if (d <= sumR) { isGood = false; break; }
            }
            if (isGood) res.push(x);
        }
        console.log(res.join(" "));
    }
}
main();

